import art.Art
import hvac_visibility_priority_supervisor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait CriticalFaultRecoveryOwner_supervision_criticalFaultRecoveryOwner_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner)
  }

  /** helper function to set the values of all input ports.
   * @param recoveryAcknowledgment payload for data port recoveryAcknowledgment
   * @param criticalElectrical payload for data port criticalElectrical
   * @param criticalEquipment payload for data port criticalEquipment
   * @param visibilityFault payload for data port visibilityFault
   */
  def put_concrete_inputs(recoveryAcknowledgment : HVAC_Visibility_Priority_Supervisor.RecoveryAcknowledgment.Type,
                          criticalElectrical : HVAC_Visibility_Priority_Supervisor.ElectricalCriticality.Type,
                          criticalEquipment : HVAC_Visibility_Priority_Supervisor.EquipmentCriticality.Type,
                          visibilityFault : HVAC_Visibility_Priority_Supervisor.VisibilityCriticality.Type): Unit = {
    put_recoveryAcknowledgment(recoveryAcknowledgment)
    put_criticalElectrical(criticalElectrical)
    put_criticalEquipment(criticalEquipment)
    put_visibilityFault(visibilityFault)
  }


  /** helper function to check CriticalFaultRecoveryOwner_supervision_criticalFaultRecoveryOwner's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param recoveryReport method that will be called with the value of the outgoing data
   *        port 'recoveryReport'.
   */
  def check_concrete_output(recoveryReport: HVAC_Visibility_Priority_Supervisor.RecoveryReport => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val recoveryReportValue: HVAC_Visibility_Priority_Supervisor.RecoveryReport = get_recoveryReport().get
    if(!recoveryReport(recoveryReportValue)) {
      testFailures = testFailures :+ st"'recoveryReport' did not match expected: value of the outgoing data port is ${recoveryReportValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_recoveryAcknowledgment(value : HVAC_Visibility_Priority_Supervisor.RecoveryAcknowledgment.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner.operational_api.recoveryAcknowledgment_Id, HVAC_Visibility_Priority_Supervisor.RecoveryAcknowledgment_Payload(value))
  }

  // setter for in DataPort
  def put_criticalElectrical(value : HVAC_Visibility_Priority_Supervisor.ElectricalCriticality.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner.operational_api.criticalElectrical_Id, HVAC_Visibility_Priority_Supervisor.ElectricalCriticality_Payload(value))
  }

  // setter for in DataPort
  def put_criticalEquipment(value : HVAC_Visibility_Priority_Supervisor.EquipmentCriticality.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner.operational_api.criticalEquipment_Id, HVAC_Visibility_Priority_Supervisor.EquipmentCriticality_Payload(value))
  }

  // setter for in DataPort
  def put_visibilityFault(value : HVAC_Visibility_Priority_Supervisor.VisibilityCriticality.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner.operational_api.visibilityFault_Id, HVAC_Visibility_Priority_Supervisor.VisibilityCriticality_Payload(value))
  }

  // getter for out DataPort
  def get_recoveryReport(): Option[HVAC_Visibility_Priority_Supervisor.RecoveryReport] = {
    val value: Option[HVAC_Visibility_Priority_Supervisor.RecoveryReport] = get_recoveryReport_payload() match {
      case Some(HVAC_Visibility_Priority_Supervisor.RecoveryReport_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port recoveryReport.  Expecting 'HVAC_Visibility_Priority_Supervisor.RecoveryReport_Payload' but received ${v}")
      case _ => None[HVAC_Visibility_Priority_Supervisor.RecoveryReport]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_recoveryReport_payload(): Option[HVAC_Visibility_Priority_Supervisor.RecoveryReport_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.HVACSupervisor_Instance_supervision_criticalFaultRecoveryOwner.initialization_api.recoveryReport_Id).asInstanceOf[Option[HVAC_Visibility_Priority_Supervisor.RecoveryReport_Payload]]
  }

}
